["from datetime import datetime

# Define the JSON schema
json_schema = {
    "type": "object",
    "properties": {
        "claim_text": {"type": "string"},
        "claim": {
            "type": "object",
            "properties": {
                "header": {"$ref": "#/$defs/ClaimHeader"},
                "incident_description": {"anyOf": [{"$ref": "#/$defs/IncidentDescription"}, {"type": "null"}], "description": "Structured incident details"},
                "insured_objects": {"anyOf": [{"type": "array", "items": {"$ref": "#/$defs/InsuredObject"}}, {"type": "null"}], "default": null, "description": "List of insured objects involved, if applicable"},
                "policy_details": {"anyOf": [{"$ref": "#/$defs/PolicyDetails"}, {"type": "null"}], "default": null, "description": "Policy information if available"}
            },
            "required": ["header", "incident_description", "insured_objects", "policy_details"],
            "title": "InsuranceClaim"
        },
        "header": {
            "type": "object",
            "properties": {
                "channel": {"anyOf": [{"type": "string", "enum": ["Email", "Phone", "Portal", "In-Person"]}, {"type": "null"}], "description": "Channel used to report claim", "title": "Channel"},
                "claim_id": {"anyOf": [{"type": "string"}, {"type": "null"}], "description": "Claim ID in format CLM-XXXXXX, where X is a digit", "title": "Claim Id"},
                "incident_date": {"anyOf": [{"type": "string", "format": "date"}, {"type": "null"}], "description": "Date incident occurred in YYYY-MM-DD format", "title": "Incident Date"},
                "report_date": {"anyOf": [{"type": "string", "format": "date"}, {"type": "null"}], "description": "Date claim was reported in YYYY-MM-DD format", "title": "Report Date"},
                "reported_by": {"anyOf": [{"type": "string", "minLength": 1}, {"type": "null"}], "description": "Full name of person reporting claim", "title": "Reported By"},
                "required": ["claim_id", "report_date", "incident_date", "reported_by", "channel"],
                "title": "ClaimHeader"
            },
            "IncidentDescription": {
                "type": "object",
                "properties": {
                    "estimated_damage_amount": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null, "description": "Estimated damage in USD without currency symbol", "title": "Estimated Damage Amount"},
                    "incident_type": {"type": "string", "description": "Specific standardized incident type", "enum": ["rear_end_collision", "side_impact_collision", "head_on_collision", "parking_lot_collision", "house_fire", "kitchen_fire", "electrical_fire", "burst_pipe_flood", "storm_damage", "roof_leak", "slip_and_fall", "property_injury", "product_liability", "theft_burglary", "vandalism"], "title": "Incident Type"},
                    "location_type": {"type": "string", "description": "Standardized location type where incident occurred", "enum": ["intersection", "highway", "parking_lot", "driveway", "residential_street", "residence_interior", "residence_exterior", "commercial_property", "public_property"], "title": "Location Type"},
                    "police_report_number": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Police report number if applicable", "title": "Police Report Number"},
                    "required": ["incident_type", "location_type"],
                    "title": "IncidentDescription"
                },
                "InsuredObject": {
                    "type": "object",
                    "properties": {
                        "estimated_value": {"anyOf": [{"type": "integer"}, {"type": "null"]

["{

    "claim": "{\"claim_id\": \"POL-314055462\", \"report_date\": \"2025-08-30\", \"incident_date\": \"2025-08-28\", \"reported_by\": \"David Johnson\", \"channel\": \"Phone call received\", \"incident_type\": \"fall\", \"location_type\": \"residential_street\", \"police_report_number\": \"CLM-699674\", \"incident_description\": \"This guy, I think his name is Martin—he was visiting, and I guess he slipped on the edge of the sidewalk right by my property, but the thing is, I’m pretty sure that’s technically city property. Like, the part between the sidewalk and the street; everyone always says we’re responsible for keeping it mowed, but I didn’t really think about liability before this. Martin went down hard—just totally lost his balance and landed awkward on his arm. I called 911 because he was in a lot of pain, and we waited for the ambulance together. The neighbors were out watching; Judy from next door actually brought out some water, so if you need to talk to anyone else about what they saw, she was there, although she’s got a lot going on with her own house since she’s been redoing her porch.\", \"required\": [\"incident_type\", \"location_type\", \"reported_by\", \"channel\", \"incident_description\"], \"title\": \"InsuranceClaim\"}"

}"]

