    "claim": "{\"claim_id\": \"CLM-531517\", \"report_date\": \"2025-08-22\", \"incident_date\": \"2025-08-22\", \"reported_by\": \"David Davis\", \"channel\": \"Phone\", \"incident_type\": \"slip_and_fall\", \"location_type\": \"store\", \"police_report_number\": \"PR-20250822-6127\", \"insured_object\": \"cinnamon bread\", \"object_id\": \"\", \"object_type\": \"food\", \"year\": \"2025\", \"estimated_damage_amount\": \"\", \"incident_description\": \"A customer slipped and fell in the front by the big window near the display with the plants and the birthday cards. Someone had spilled water, I guess though I swear we try to keep that area dry, especially after we mop in the morning. It wasn’t even raining, so I don’t know where the water came from, maybe from the flower buckets.\", \"required\": [\"incident_type\", \"location_type\", \"police_report_number\", \"insured_object\", \"object_id\", \"object_type\", \"year\", \"estimated_damage_amount\", \"incident_description\"], \"title\": \"Slip and Fall Incident\"}"

}"]

